insert into public.posts (slug, title, excerpt, body_md, body_html, author_name, tags, status, published_at) values ('welcome-to-base-suite', 'Welcome to Base Suite', 'Your website, customers and support in one place. Here''s a quick tour of what you can do from the admin portal.', 'Base Suite gives your business a fast website **and** the tools to run it.

