insert into public.posts (slug, title, excerpt, body_md, body_html, author_name, tags, status, published_at) values ('five-tips-for-a-homepage-that-converts', '5 tips for a homepage that converts', 'Small changes that make visitors stay, trust you and take the next step.', 'Your homepage has one job: help the right visitor take the next step.

1. **Say what you do in one sentence.** Put it in the hero title.
2. **Show proof early.** A stats bar or two testimonials go a long way.
3. **One primary action.** Make it obvious — "Book a demo" or "Get started".
4. **Answer objections.** An FAQ section handles the questions people won''t ask.
5. **Make it fast.** Every second of load time costs you visitors.

All five are built into the homepage editor. Try reordering your features so the most important one comes first.', '<p>Your homepage has one job: help the right visitor take the next step.</p>
<ol>
<li><strong>Say what you do in one sentence.</strong> Put it in the hero title.</li>
<li><strong>Show proof early.</strong> A stats bar or two testimonials go a long way.</li>
<li><strong>One primary action.</strong> Make it obvious — "Book a demo" or "Get started".</li>
<li><strong>Answer objections.</strong> An FAQ section handles the questions people won''t ask.</li>
<li><strong>Make it fast.</strong> Every second of load time costs you visitors.</li>
</ol>
<p>All five are built into the homepage editor. Try reordering your features so the most important one comes first.</p>
', 'The Base Suite team', array['guides', 'marketing']::text[], 'published', '2026-10-25T05:04:35.686Z') on conflict (slug) do nothing;
insert into public.posts (slug, title, excerpt, body_md, body_html, author_name, tags, status, published_at) values ('how-we-handle-your-data', 'How we handle your data', 'Security isn''t an add-on. Here''s how your information is protected.', 'We take your data seriously. A few things we do by default:

- Every database table is protected with **row-level security**.
- Staff access is **role-based** and every admin change is **audit-logged**.
- Payments are handled by **Stripe** — card details never touch our servers.
- The site loads **no third-party tracking scripts**.

Questions? [Get in touch](/contact_us).', '<p>We take your data seriously. A few things we do by default:</p>
<ul>
<li>Every database table is protected with <strong>row-level security</strong>.</li>
<li>Staff access is <strong>role-based</strong> and every admin change is <strong>audit-logged</strong>.</li>
<li>Payments are handled by <strong>Stripe</strong> — card details never touch our servers.</li>
<li>The site loads <strong>no third-party tracking scripts</strong>.</li>
</ul>
<p>Questions? <a href="/contact_us">Get in touch</a>.</p>
', 'The Base Suite team', array['security']::text[], 'published', '2026-10-14T05:04:35.686Z') on conflict (slug) do nothing;
